<script setup lang="ts">
import type { BsSupplierOrderCopy, BsSupplierOrderView, BsSupplierOrderRow, BsSupplierOrderForm, BsSupplierOrderFormLine, BsSupplierOrderOperationForm, BsSupplierOrderPicker, BsSupplierOrderLineView } from '../types/supplierOrderPresentation'
const props = defineProps<{ copy: BsSupplierOrderCopy; view: BsSupplierOrderView; rows: BsSupplierOrderRow[]; supplierPicker: BsSupplierOrderPicker; lineViews: BsSupplierOrderLineView[] }>()
const search = defineModel<string>('search', { required: true }), status = defineModel<string>('status', { required: true })
const page = defineModel<number>('page', { required: true }), historyPage = defineModel<number>('historyPage', { required: true }), receiptPage = defineModel<number>('receiptPage', { required: true })
const editorOpen = defineModel<boolean>('editorOpen', { required: true }), detailOpen = defineModel<boolean>('detailOpen', { required: true }), operationOpen = defineModel<boolean>('operationOpen', { required: true })
const form = defineModel<BsSupplierOrderForm>('form', { required: true }), operation = defineModel<BsSupplierOrderOperationForm>('operation', { required: true })
const emit = defineEmits<{ retry: []; retryDetail: []; add: []; open: [id: string]; edit: []; operate: [action: 'issue' | 'cancel' | 'receive']; submit: []; submitOperation: []; print: []; addLine: []; removeLine: [key: string]; source: [key: string, value: string]; pickerSearch: [kind: 'product' | 'supplier', query: string]; pickerMore: [kind: 'product' | 'supplier']; pickerRetry: [kind: 'product' | 'supplier'] }>()
function change<K extends keyof BsSupplierOrderForm>(key: K, value: BsSupplierOrderForm[K]) { form.value = { ...form.value, [key]: value } }
function lineChange<K extends keyof BsSupplierOrderFormLine>(id: string, key: K, value: BsSupplierOrderFormLine[K]) { change('lines', form.value.lines.map(line => line.key === id ? { ...line, [key]: value } : line)) }
function operationLine(id: string, key: 'quantity' | 'barcodes', value: string) { operation.value = { ...operation.value, lines: operation.value.lines.map(line => line.id === id ? { ...line, [key]: value } : line) } }
const columns = computed(() => [{ key: 'number', field: 'number', header: props.copy.number }, { key: 'vendor', field: 'vendor', header: props.copy.vendor }, { key: 'status', field: 'status', header: props.copy.status }, { key: 'expected', field: 'expected', header: props.copy.expected }, { key: 'total', field: 'total', header: props.copy.total }, { key: 'date', field: 'date', header: props.copy.date }, { key: 'actions', header: props.copy.actions }])
const lineColumns = computed(() => [{ key: 'name', field: 'name', header: props.copy.product }, { key: 'quantity', field: 'quantity', header: props.copy.quantity }, { key: 'cost', field: 'cost', header: props.copy.cost }, { key: 'total', field: 'total', header: props.copy.total }, { key: 'received', field: 'received', header: props.copy.received }, { key: 'remaining', field: 'remaining', header: props.copy.remaining }])
const receiptColumns = computed(() => [{ key: 'invoice', header: props.copy.invoice }, { key: 'total', field: 'total', header: props.copy.invoiceTotal }, { key: 'date', field: 'date', header: props.copy.date }, { key: 'reason', field: 'reason', header: props.copy.reason }, { key: 'actor', field: 'actor', header: props.copy.actor }])
const eventColumns = computed(() => [{ key: 'action', field: 'action', header: props.copy.actions }, { key: 'reason', field: 'reason', header: props.copy.reason }, { key: 'date', field: 'date', header: props.copy.date }, { key: 'actor', field: 'actor', header: props.copy.actor }])
</script>
<template>
 <BsStack gap="lg">
  <BsPageHeader :title="copy.title" :subtitle="copy.subtitle"><template #actions><BsButton v-if="view.available && view.canCreate" :disabled="view.locked || editorOpen || operationOpen" @click="emit('add')">{{ copy.add }}</BsButton></template></BsPageHeader>
  <BsPanel v-if="!view.available" padding="md"><BsText as="p">{{ copy.noShop }}</BsText></BsPanel>
  <BsStack v-else gap="md">
   <BsSelect :model-value="status" @update:model-value="status = String($event ?? '')" :label="copy.status" :options="view.statusOptions" option-label="label" option-value="value" :disabled="view.locked" />
   <BsDataTable :value="rows" :label="copy.title" :columns="columns" data-key="id" :loading="view.loading" :error="view.error || null" searchable :search-label="copy.search" lazy paginator :rows="20" :first="(page - 1) * 20" :total-records="view.total" @search="search = $event" @page="page = $event.page + 1" @retry="emit('retry')"><template #cell-actions="{ row }"><BsButton variant="secondary" :disabled="view.locked || editorOpen || operationOpen" @click="emit('open', row.id)">{{ copy.open }}</BsButton></template><template #empty><BsText as="p">{{ copy.empty }}</BsText></template></BsDataTable>
  </BsStack>
  <BsDialog v-model:visible="detailOpen" :title="view.detail.title || copy.title" :pending="editorOpen || operationOpen || view.locked" size="lg">
   <BsText v-if="view.detail.loading" role="status">{{ copy.retry }}</BsText><BsStack v-else-if="view.detail.error"><BsText role="alert">{{ view.detail.error }}</BsText><BsButton @click="emit('retryDetail')">{{ copy.retry }}</BsButton></BsStack>
   <BsStack v-else gap="md">
    <BsText v-if="view.detail.actionError" role="alert">{{ view.detail.actionError }}</BsText><BsText as="p">{{ view.detail.status }}</BsText><BsText as="p" tone="muted">{{ view.detail.notice }}</BsText>
    <BsDescriptionList><BsDescriptionItem v-for="field in view.detail.fields" :key="field.label" :term="field.label">{{ field.value }}</BsDescriptionItem></BsDescriptionList>
    <BsInline wrap><BsButton v-if="view.detail.canEdit" :disabled="view.locked" @click="emit('edit')">{{ copy.edit }}</BsButton><BsButton v-if="view.detail.canIssue" :disabled="view.locked" @click="emit('operate', 'issue')">{{ copy.issue }}</BsButton><BsButton v-if="view.detail.canReceive" :disabled="view.locked" @click="emit('operate', 'receive')">{{ copy.receive }}</BsButton><BsButton v-if="view.detail.canCancel" variant="secondary" :disabled="view.locked" @click="emit('operate', 'cancel')">{{ copy.cancelOrder }}</BsButton><BsButton v-if="view.detail.canPrint" variant="secondary" :disabled="view.locked" @click="emit('print')">{{ copy.print }}</BsButton></BsInline>
    <BsDataTable :value="view.detail.lines" :label="copy.lines" :columns="lineColumns" data-key="id" />
    <BsDataTable :value="view.detail.receipts" :label="copy.receiptHistory" :columns="receiptColumns" data-key="id" lazy paginator :rows="20" :first="(receiptPage - 1) * 20" :total-records="view.detail.receiptTotal" @page="receiptPage = $event.page + 1"><template #cell-invoice="{ row }"><BsLink :to="row.to">{{ row.invoice }}</BsLink></template></BsDataTable>
    <BsDataTable :value="view.detail.events" :label="copy.history" :columns="eventColumns" data-key="id" lazy paginator :rows="20" :first="(historyPage - 1) * 20" :total-records="view.detail.historyTotal" @page="historyPage = $event.page + 1" />
   </BsStack>
   <template #footer><BsButton :disabled="editorOpen || operationOpen || view.locked" @click="detailOpen = false">{{ copy.close }}</BsButton></template>
  </BsDialog>
  <BsRecordActionDialog v-model:visible="editorOpen" :title="view.editor.title" :dirty="view.editor.dirty" :pending="view.editor.pending" :close-blocked="view.locked" :error="view.editor.error" :submit-label="copy.save" :cancel-label="copy.cancel" pinned-actions size="lg" @submit="emit('submit')">
   <BsText as="p" tone="muted">{{ view.editor.notice }}</BsText>
   <BsEntityPicker :model-value="form.vendorId" :label="copy.vendor" :options="supplierPicker.options" option-label="name" option-value="id" :loading="supplierPicker.loading" :error="supplierPicker.error" :has-more="supplierPicker.hasMore" :load-more-label="supplierPicker.more" :retry-label="supplierPicker.retry" :disabled="view.locked" @search="emit('pickerSearch', 'supplier', $event)" @load-more="emit('pickerMore', 'supplier')" @retry="emit('pickerRetry', 'supplier')" @update:model-value="change('vendorId', String($event ?? ''))" />
   <BsField v-slot="field" for="supplier-order-expected" :label="copy.expected"><BsInput :id="field.id" :model-value="form.expectedOn" type="date" :disabled="view.locked" @update:model-value="change('expectedOn', String($event))" /></BsField>
   <BsStack v-for="(line, index) in form.lines" :key="line.key" gap="sm">
    <BsHeading :level="3">{{ copy.product }} {{ index + 1 }}</BsHeading>
    <BsEntityPicker :model-value="line.productId" :label="copy.product" :options="lineViews[index]?.picker.options || []" option-label="name" option-value="id" :loading="lineViews[index]?.picker.loading" :error="lineViews[index]?.picker.error" :has-more="lineViews[index]?.picker.hasMore" :load-more-label="lineViews[index]?.picker.more || copy.retry" :retry-label="lineViews[index]?.picker.retry || copy.retry" :disabled="view.locked" @search="emit('pickerSearch', 'product', $event)" @load-more="emit('pickerMore', 'product')" @retry="emit('pickerRetry', 'product')" @update:model-value="emit('source', line.key, String($event ?? ''))" />
    <BsGrid :columns="2"><BsField v-slot="field" :for="`supplier-order-quantity-${line.key}`" :label="copy.quantity"><BsInput :id="field.id" :model-value="line.quantity" inputmode="decimal" :disabled="view.locked" required @update:model-value="lineChange(line.key, 'quantity', String($event))" /></BsField><BsField v-slot="field" :for="`supplier-order-unit-${line.key}`" :label="copy.unit"><BsSelect :input-id="field.id" :model-value="line.unit" :label="copy.unit" :options="lineViews[index]?.units || []" option-label="label" option-value="value" :loading="lineViews[index]?.loading" :disabled="view.locked || lineViews[index]?.loading" @update:model-value="lineChange(line.key, 'unit', String($event ?? ''))" /></BsField></BsGrid>
    <BsField v-slot="field" :for="`supplier-order-cost-${line.key}`" :label="copy.cost"><BsInput :id="field.id" :model-value="line.cost" inputmode="decimal" :disabled="view.locked" required @update:model-value="lineChange(line.key, 'cost', String($event))" /></BsField>
    <BsButton variant="text" :disabled="view.locked" @click="emit('removeLine', line.key)">{{ copy.remove }}</BsButton>
   </BsStack>
   <BsButton variant="secondary" :disabled="view.locked || form.lines.length >= 100" @click="emit('addLine')">{{ copy.addLine }}</BsButton>
   <BsField v-slot="field" for="supplier-order-notes" :label="copy.notes"><BsTextarea :id="field.id" :model-value="form.notes" :disabled="view.locked" :maxlength="1000" @update:model-value="change('notes', String($event))" /></BsField>
   <BsField v-slot="field" for="supplier-order-reason" :label="copy.reason"><BsTextarea :id="field.id" :model-value="form.reason" :disabled="view.locked" required :minlength="3" :maxlength="1000" @update:model-value="change('reason', String($event))" /></BsField>
  </BsRecordActionDialog>
  <BsRecordActionDialog v-model:visible="operationOpen" :title="view.operation.title" :dirty="view.operation.dirty" :pending="view.operation.pending" :close-blocked="view.locked" :error="view.operation.error" :submit-label="view.operation.title" :cancel-label="copy.cancel" pinned-actions size="lg" @submit="emit('submitOperation')">
   <BsText as="p">{{ view.operation.summary }}</BsText><BsText as="p" tone="muted">{{ view.operation.notice }}</BsText>
   <BsStack v-if="view.operation.isReceipt" gap="md">
    <BsGrid :columns="2"><BsField v-slot="field" for="supplier-receipt-date" :label="copy.receivedOn"><BsInput :id="field.id" :model-value="operation.receivedOn" type="date" :disabled="view.locked" required @update:model-value="operation = { ...operation, receivedOn: String($event) }" /></BsField><BsField v-slot="field" for="supplier-receipt-invoice" :label="copy.invoiceNumber"><BsInput :id="field.id" :model-value="operation.invoiceNumber" :disabled="view.locked" :maxlength="120" @update:model-value="operation = { ...operation, invoiceNumber: String($event) }" /></BsField></BsGrid>
    <BsStack v-for="line in operation.lines" :key="line.id" gap="sm"><BsText as="p">{{ line.name }} · {{ copy.remaining }} {{ line.remaining }} {{ line.unit }}</BsText><BsField v-slot="field" :for="`supplier-receipt-quantity-${line.id}`" :label="`${line.name} (${line.unit})`"><BsInput :id="field.id" :model-value="line.quantity" inputmode="decimal" :disabled="view.locked" @update:model-value="operationLine(line.id, 'quantity', String($event))" /></BsField><BsField v-if="line.reelTracked" v-slot="field" :for="`supplier-receipt-barcodes-${line.id}`" :label="`${copy.barcodes} · ${line.name}`"><BsTextarea :id="field.id" :model-value="line.barcodes" dir="ltr" :disabled="view.locked" :maxlength="81000" @update:model-value="operationLine(line.id, 'barcodes', String($event))" /></BsField></BsStack>
   </BsStack>
   <BsField v-slot="field" for="supplier-receipt-reason" :label="copy.reason"><BsTextarea :id="field.id" :model-value="operation.reason" :disabled="view.locked" required :minlength="3" :maxlength="1000" @update:model-value="operation = { ...operation, reason: String($event) }" /></BsField>
  </BsRecordActionDialog>
 </BsStack>
</template>
